/** Private durable allocation metadata; values grant neither execution nor backend authority. */
import type { Branded } from '@deepseek-ai/dsh-brand'
import type { AccountId, OwnerEpoch } from '@deepseek-ai/dsh-pe-cloud-runtime/types'
import type { SessionId } from '@deepseek-ai/dsh-session'
import type { WorkspaceId } from '@deepseek-ai/dsh-workspace'
import type { ExecutionCapability } from './types.ts'

/** Allocation identity generated by the Root service before any backend create. */
export type AllocationId = Branded<'pe-sandbox-allocation-id'>

/** Nonterminal states remain exclusive for one account/native Session/epoch. */
export type AllocationState = 'creating' | 'ready' | 'uncertain' | 'stopping' | 'failed' | 'released'

/** One real, bounded PostgreSQL statement; rejection after submission may leave a mutation unknown. */
export interface AllocationQuery {
  /**
   * Submit store-owned SQL with bound parameters and retain its actual connection/statement settlement.
   * Caller deadlines must not reject this promise while underlying work remains running.
   * @param text - one statement, including the atomic migration DO block.
   * @param values - text/null parameters, without interpolation or backend selection.
   * @returns actual driver rows; durable JSON still requires store validation.
   */
  query(text: string, values: readonly (string | null)[]): Promise<{ readonly rows: readonly unknown[] }>
}

/** Explicit limits for serialized input/results and retained pending/unknown responsibilities. */
export interface AllocationStoreLimits {
  readonly maxFieldBytes: number
  readonly maxInputBytes: number
  readonly maxRowBytes: number
  readonly maxResultBytes: number
  readonly maxRows: number
  readonly maxCapabilities: number
  readonly maxPendingQueries: number
  readonly maxMutationResponsibilities: number
  readonly maxRetainedBytes: number
}

/** Every exact-id read and CAS binds the complete immutable native scope. */
export interface AllocationScope {
  readonly allocationId: AllocationId
  readonly accountId: AccountId
  readonly sessionId: SessionId
  readonly workspaceId: WorkspaceId
  readonly epoch: OwnerEpoch
}

/** Root-approved create intent; no SDK call, host path, secret or caller-selected URL is accepted. */
export interface AllocationCreateIntent extends AllocationScope {
  readonly environmentVersion: string
  readonly provider: string
  readonly projectMountVersion: string
  readonly requestedAt: string
  readonly createDeadlineAt: string
}

/** Validated immutable durable row; observations do not establish backend stopping proof. */
export interface SandboxAllocation extends AllocationCreateIntent {
  readonly state: AllocationState
  readonly sandboxId: string | null
  readonly lastActivityAt: string
  readonly lastCheckedAt: string
  readonly runtimeIdentity: string | null
  readonly executionProtocolVersion: string | null
  readonly executionCapabilities: readonly ExecutionCapability[]
  readonly failureCode: string | null
}

/** A matching existing record is never an instruction to replay backend create. */
export interface AllocationBeginResult {
  readonly allocation: SandboxAllocation
  readonly inserted: boolean
}

/** State is checked with the exact identity; an old epoch cannot update another row. */
export interface AllocationExpectation extends AllocationScope {
  readonly state: AllocationState
}

/** Only explicit Root no-create/stop methods can enter the terminal states. */
export type AllocationChange =
  | Readonly<{
    to: 'ready'
    sandboxId: string
    runtimeIdentity: string
    executionProtocolVersion: string
    executionCapabilities: readonly ExecutionCapability[]
  }>
  | Readonly<{ to: 'uncertain'; failureCode: string; sandboxId?: string }>
  | Readonly<{ to: 'stopping'; sandboxId?: string; failureCode?: string }>

/** A null listing scope enumerates all nonterminal rows for trusted Root startup recovery. */
export interface AllocationEpochScope {
  readonly accountId: AccountId
  readonly epoch: OwnerEpoch
}

/** Keyset page; an exact full page may require a final empty query. Not a transaction snapshot. */
export interface AllocationPage {
  readonly allocations: readonly SandboxAllocation[]
  readonly nextCursor: AllocationId | null
}
